const THREE = require('three');

// 黑色西方龙坐骑：蹲坐抬翼、长颈、四足、长尾刃尖，双翼与尾节可独立驱动。
const ASSET_BRIEF = {
  identity: {
    objectClass: 'western-dragon-mount',
    confidence: 0.92,
    assumptions: [
      'Single reference view; far-side wing, far-side legs and back surface are mirrored from the visible side.',
      'Saddle is added as a small leather riding pad because the module is rideable.',
    ],
  },
  orientation: {
    up: '+Y',
    front: '+Z',
  },
  silhouette: {
    primaryMasses: ['Torso', 'Chest', 'HipsMass', 'NeckChain', 'WingLeftRoot', 'WingRightRoot', 'TailRoot'],
    proportions: 'Sitting quadruped, shoulders high, neck raised, wings held high and half spread, long tail curling up to a blade tip.',
    identityCues: ['Amber slit eyes', 'Backward horns', 'Segmented belly plates', 'Scalloped wing membranes', 'Blade cluster tail tip'],
  },
  parts: [
    { id: 'Torso', level: 'macro', role: 'primary body mass', parent: 'VisualRoot', topologyClass: 'continuous-sculpt', geometryStrategy: 'overlapping ellipsoid volumes', materialRole: 'hide', moving: false },
    { id: 'BellyPlates', level: 'meso', role: 'segmented belly armor', parent: 'VisualRoot', topologyClass: 'surface-relief', geometryStrategy: 'flattened lens plates', materialRole: 'bellyPlate', moving: false },
    { id: 'NeckRoot', level: 'macro', role: 'neck and head chain', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'tapered segment chain', materialRole: 'hide', moving: true, pivotStrategy: 'root pivot at chest' },
    { id: 'HeadRoot', level: 'macro', role: 'skull, snout, horns and eyes', parent: 'Neck03', topologyClass: 'assembled-solid', geometryStrategy: 'ellipsoid skull with tapered snout and horn cones', materialRole: 'hide', moving: true },
    { id: 'WingLeftRoot', level: 'macro', role: 'left wing assembly', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'arm bones plus scalloped extruded membrane', materialRole: 'membrane', moving: true, pivotStrategy: 'hinge pivot at shoulder' },
    { id: 'WingRightRoot', level: 'macro', role: 'right wing assembly', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'mirrored arm bones plus scalloped extruded membrane', materialRole: 'membrane', moving: true, pivotStrategy: 'hinge pivot at shoulder' },
    { id: 'TailRoot', level: 'macro', role: 'tail chain and blade tip', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'tapered segment chain with dorsal spikes', materialRole: 'hide', moving: true, pivotStrategy: 'root pivot at hips' },
    { id: 'LegFL', level: 'macro', role: 'front left leg', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'tapered limb segments with clawed foot', materialRole: 'hide', moving: false },
    { id: 'LegFR', level: 'macro', role: 'front right leg', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'tapered limb segments with clawed foot', materialRole: 'hide', moving: false },
    { id: 'LegBL', level: 'macro', role: 'hind left leg', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'crouched thigh and shin with clawed foot', materialRole: 'hide', moving: false },
    { id: 'LegBR', level: 'macro', role: 'hind right leg', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'crouched thigh and shin with clawed foot', materialRole: 'hide', moving: false },
    { id: 'Saddle', level: 'meso', role: 'riding pad and seat anchor', parent: 'VisualRoot', topologyClass: 'assembled-solid', geometryStrategy: 'rounded leather pad with cantle and straps', materialRole: 'saddleLeather', moving: false },
  ],
  details: [
    { id: 'BellyPlates', region: 'chest and abdomen front', kind: 'ridge', affects: 'geometry', mapsTo: 'BellyPlates_Plate', implementation: 'eight flattened lens solids', scale: '0.2-0.33 m wide', confidence: 0.9 },
    { id: 'DorsalSpikes', region: 'spine ridge', kind: 'ridge', affects: 'geometry', mapsTo: 'BodySpikes_Spine', implementation: 'tapered bone cones', scale: '0.12-0.22 m tall', confidence: 0.7 },
    { id: 'AmberEyes', region: 'head', kind: 'emissive', affects: 'material', mapsTo: 'Head_Eye', implementation: 'amber emissive sphere with dark slit', scale: '0.05-0.09 m', confidence: 0.95 },
    { id: 'TailBlade', region: 'tail tip', kind: 'silhouette-break', affects: 'geometry', mapsTo: 'TailBlade', implementation: 'dark bone spikes around a dark red fin', scale: '0.4-0.6 m', confidence: 0.85 },
    { id: 'ScallopedMembrane', region: 'wings', kind: 'outline-break', affects: 'geometry', mapsTo: 'WingLeftRoot_WingLeftMembrane', implementation: 'extruded polygon with scalloped trailing edge', scale: '1.6 m reach', confidence: 0.9 },
  ],
  materialRoles: {
    hide: { baseColor: 0x24262b, roughness: 0.62, metalness: 0.05 },
    hideDark: { baseColor: 0x15161a, roughness: 0.72, metalness: 0.02 },
    bellyPlate: { baseColor: 0x666c74, roughness: 0.55, metalness: 0.03 },
    membrane: { baseColor: 0x26262c, roughness: 0.86, metalness: 0.0 },
    bone: { baseColor: 0x4b4943, roughness: 0.52, metalness: 0.06 },
    claw: { baseColor: 0x7a776e, roughness: 0.34, metalness: 0.12 },
    eye: { baseColor: 0xd9a12b, roughness: 0.25, metalness: 0.0 },
    pupil: { baseColor: 0x0a0a0b, roughness: 0.4, metalness: 0.0 },
    saddleLeather: { baseColor: 0x3c2b22, roughness: 0.78, metalness: 0.02 },
    saddleMetal: { baseColor: 0x9a7b3e, roughness: 0.34, metalness: 0.82 },
    bladeRed: { baseColor: 0x4a1719, roughness: 0.5, metalness: 0.08 },
  },
  readiness: {
    pivots: ['WingLeftRoot', 'WingRightRoot', 'TailRoot', 'NeckRoot'],
    sockets: ['Saddle/SeatAnchor'],
    anchors: ['Saddle/SeatAnchor'],
    colliderIntent: [{ partId: 'Torso', type: 'convex', size: [1.4, 3.2, 6.4] }],
  },
};

function makeMaterials() {
  const materials = {};
  Object.entries(ASSET_BRIEF.materialRoles).forEach(([id, role]) => {
    const material = new THREE.MeshStandardMaterial({
      color: role.baseColor,
      roughness: role.roughness,
      metalness: role.metalness,
      side: THREE.FrontSide,
    });
    material.name = id;
    materials[id] = material;
  });
  materials.eye.emissive = new THREE.Color(0x8a5a08);
  materials.eye.emissiveIntensity = 0.85;
  materials.bladeRed.emissive = new THREE.Color(0x2a0708);
  materials.bladeRed.emissiveIntensity = 0.4;
  return materials;
}

function makeGroup(parent, name, position, rotation) {
  const group = new THREE.Group();
  group.name = name;
  if (position) group.position.set(position[0], position[1], position[2]);
  if (rotation) group.rotation.set(rotation[0], rotation[1], rotation[2]);
  parent.add(group);
  return group;
}

function addEllipsoid(parent, name, material, position, scale, segments, rings) {
  const geometry = new THREE.SphereGeometry(1, segments || 24, rings || 16);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = name;
  mesh.position.set(position[0], position[1], position[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);
  parent.add(mesh);
  return mesh;
}

const UP_AXIS = new THREE.Vector3(0, 1, 0);

function addSegment(parent, name, material, start, end, radiusStart, radiusEnd, radialSegments) {
  const direction = new THREE.Vector3().subVectors(end, start);
  const length = direction.length();
  if (!isFinite(length) || length <= 0) return null;
  const geometry = new THREE.CylinderGeometry(
    Math.max(radiusEnd, 0.001),
    Math.max(radiusStart, 0.001),
    length,
    radialSegments || 12,
    1,
    false,
  );
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = name;
  mesh.position.copy(start).add(end).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(UP_AXIS, direction.clone().normalize());
  parent.add(mesh);
  return mesh;
}

function addJoint(parent, name, material, position, radius, segments) {
  return addEllipsoid(parent, name, material, position, [radius, radius, radius], segments || 16, 12);
}

function addCone(parent, name, material, start, end, radius, radialSegments) {
  return addSegment(parent, name, material, start, end, radius, 0.004, radialSegments || 10);
}

function buildBellyPlates(parent, materials) {
  const group = makeGroup(parent, 'BellyPlates');
  const plates = [
    [0, 1.79, 0.96, 0.29, 0.15],
    [0, 1.64, 1.07, 0.32, 0.16],
    [0, 1.48, 1.12, 0.33, 0.17],
    [0, 1.32, 1.09, 0.32, 0.17],
    [0, 1.16, 1.00, 0.30, 0.16],
    [0, 1.00, 0.88, 0.27, 0.15],
    [0, 0.85, 0.72, 0.24, 0.13],
    [0, 0.72, 0.54, 0.20, 0.11],
  ];
  plates.forEach((plate, index) => {
    addEllipsoid(
      group,
      `BellyPlates_Plate${index + 1}`,
      materials.bellyPlate,
      [plate[0], plate[1], plate[2]],
      [plate[3], 0.052, plate[4]],
      20,
      12,
    );
  });
  return group;
}

function buildDorsalSpikes(parent, materials) {
  const group = makeGroup(parent, 'BodySpikes');
  const spines = [
    [0, 2.02, 0.52, 0.18, 0.45],
    [0, 2.04, 0.22, 0.19, 0.42],
    [0, 1.96, -0.06, 0.18, 0.40],
    [0, 1.84, -0.34, 0.16, 0.38],
    [0, 1.68, -0.95, 0.13, 0.34],
    [0, 1.46, -1.22, 0.11, 0.32],
  ];
  spines.forEach((spine, index) => {
    addCone(
      group,
      `BodySpikes_Spine${index + 1}`,
      materials.bone,
      new THREE.Vector3(spine[0], spine[1], spine[2]),
      new THREE.Vector3(spine[0], spine[1] + spine[3], spine[2] - spine[3] * 0.85),
      0.055,
      10,
    );
  });
  return group;
}

function buildNeck(parent, materials) {
  const neckRoot = makeGroup(parent, 'NeckRoot', [0, 1.80, 0.84]);
  const neckDefinitions = [
    { name: 'Neck01', length: 0.28, z: 0.14, r0: 0.27, r1: 0.23 },
    { name: 'Neck02', length: 0.26, z: 0.17, r0: 0.23, r1: 0.20 },
    { name: 'Neck03', length: 0.22, z: 0.16, r0: 0.20, r1: 0.17 },
  ];

  let parentNode = neckRoot;
  let previousDefinition = null;
  neckDefinitions.forEach((definition) => {
    const pivot = makeGroup(parentNode, definition.name, previousDefinition ? [0, 0, 0] : [0, 0, 0]);
    if (previousDefinition) {
      pivot.position.set(0, 0, 0);
    }
    // 每段颈节从上一段末端继续生长，避免出现空气缝。
    const start = new THREE.Vector3(0, 0, 0);
    const end = new THREE.Vector3(0, definition.length, definition.z);
    addSegment(pivot, `${definition.name}_Shell`, materials.hide, start, end, definition.r0, definition.r1, 14);
    addJoint(pivot, `${definition.name}_Joint`, materials.hide, [0, 0, 0], definition.r0 * 0.98, 14);
    // 颈背骨刺
    addCone(
      pivot,
      `${definition.name}_Spike`,
      materials.bone,
      new THREE.Vector3(0, definition.r0 * 0.55, -definition.r0 * 0.35),
      new THREE.Vector3(0, definition.length + 0.13, definition.z - 0.20),
      0.045,
      8,
    );
    addJoint(pivot, `${definition.name}_End`, materials.hide, [0, definition.length, definition.z], definition.r1, 14);
    parentNode = pivot;
    previousDefinition = definition;
  });

  const headRoot = makeGroup(parentNode, 'HeadRoot', [0, 0.08, 0.10]);
  buildHead(headRoot, materials);
  return neckRoot;
}

function buildHead(parent, materials) {
  const group = makeGroup(parent, 'HeadDisplay');
  addEllipsoid(group, 'Head_Skull', materials.hide, [0, 0.10, 0.08], [0.25, 0.20, 0.32], 24, 16);
  addEllipsoid(group, 'Head_Snout', materials.hide, [0, 0.045, 0.47], [0.16, 0.105, 0.26], 20, 14);
  addEllipsoid(group, 'Head_LowerJaw', materials.hideDark, [0, -0.055, 0.45], [0.145, 0.06, 0.25], 20, 12);
  addEllipsoid(group, 'Head_NoseRidge', materials.hideDark, [0, 0.15, 0.30], [0.10, 0.05, 0.20], 18, 12);

  // 黄眼与竖瞳
  addEllipsoid(group, 'Head_EyeL', materials.eye, [0.165, 0.145, 0.225], [0.052, 0.05, 0.05], 16, 12);
  addEllipsoid(group, 'Head_EyeR', materials.eye, [-0.165, 0.145, 0.225], [0.052, 0.05, 0.05], 16, 12);
  addEllipsoid(group, 'Head_PupilL', materials.pupil, [0.192, 0.148, 0.255], [0.012, 0.034, 0.022], 10, 8);
  addEllipsoid(group, 'Head_PupilR', materials.pupil, [-0.192, 0.148, 0.255], [0.012, 0.034, 0.022], 10, 8);
  addEllipsoid(group, 'Head_BrowL', materials.hideDark, [0.15, 0.21, 0.20], [0.10, 0.04, 0.13], 16, 10);
  addEllipsoid(group, 'Head_BrowR', materials.hideDark, [-0.15, 0.21, 0.20], [0.10, 0.04, 0.13], 16, 10);

  // 向后掠的角
  addCone(group, 'Head_HornL', materials.bone,
    new THREE.Vector3(0.14, 0.24, 0.02),
    new THREE.Vector3(0.30, 0.46, -0.34), 0.065, 12);
  addCone(group, 'Head_HornR', materials.bone,
    new THREE.Vector3(-0.14, 0.24, 0.02),
    new THREE.Vector3(-0.30, 0.46, -0.34), 0.065, 12);
  addCone(group, 'Head_HornL2', materials.bone,
    new THREE.Vector3(0.20, 0.05, -0.04),
    new THREE.Vector3(0.38, 0.20, -0.34), 0.045, 10);
  addCone(group, 'Head_HornR2', materials.bone,
    new THREE.Vector3(-0.20, 0.05, -0.04),
    new THREE.Vector3(-0.38, 0.20, -0.34), 0.045, 10);
  addCone(group, 'Head_CheekSpikeL', materials.bone,
    new THREE.Vector3(0.20, 0.01, 0.06),
    new THREE.Vector3(0.33, -0.06, -0.16), 0.035, 8);
  addCone(group, 'Head_CheekSpikeR', materials.bone,
    new THREE.Vector3(-0.20, 0.01, 0.06),
    new THREE.Vector3(-0.33, -0.06, -0.16), 0.035, 8);

  // 獠牙
  const toothPositions = [
    [0.09, -0.02, 0.58], [-0.09, -0.02, 0.58],
    [0.11, -0.01, 0.44], [-0.11, -0.01, 0.44],
    [0.10, 0.0, 0.32], [-0.10, 0.0, 0.32],
  ];
  toothPositions.forEach((tooth, index) => {
    addCone(group, `Head_Tooth${index + 1}`, materials.claw,
      new THREE.Vector3(tooth[0], tooth[1], tooth[2]),
      new THREE.Vector3(tooth[0], tooth[1] - 0.08, tooth[2] + 0.02), 0.018, 8);
  });
  return group;
}

function wingOutline(side) {
  const points = [
    [0.02, 0.00],
    [0.58, 0.68],
    [1.06, 1.06],
    [1.60, 1.31],
    [1.66, 1.18],
    [1.53, 0.80],
    [1.44, 0.59],
    [1.28, 0.37],
    [1.12, 0.24],
    [0.96, 0.05],
    [0.72, -0.12],
    [0.52, -0.13],
    [0.28, -0.32],
    [0.06, -0.16],
  ];
  const mirrored = points.map((point) => [point[0] * side, point[1]]);
  if (side < 0) mirrored.reverse();
  return mirrored;
}

function buildWing(parent, materials, side) {
  const suffix = side > 0 ? 'Left' : 'Right';
  const root = makeGroup(parent, `Wing${suffix}Root`, [0.50 * side, 1.95, 0.30]);
  const display = makeGroup(root, `Wing${suffix}Display`);

  // 翅骨：肩 -> 肘 -> 腕 -> 翼尖
  addJoint(display, `Wing${suffix}_Shoulder`, materials.hide, [0, 0, 0], 0.15, 14);
  addSegment(display, `Wing${suffix}_Humerus`, materials.hide,
    new THREE.Vector3(0, 0, 0),
    new THREE.Vector3(0.58 * side, 0.68, 0.02), 0.14, 0.105, 12);
  addJoint(display, `Wing${suffix}_Elbow`, materials.hide, [0.58 * side, 0.68, 0.02], 0.105, 12);
  addSegment(display, `Wing${suffix}_Forearm`, materials.hide,
    new THREE.Vector3(0.58 * side, 0.68, 0.02),
    new THREE.Vector3(1.06 * side, 1.06, 0.00), 0.10, 0.07, 12);
  addJoint(display, `Wing${suffix}_Wrist`, materials.hide, [1.06 * side, 1.06, 0.00], 0.075, 12);
  addSegment(display, `Wing${suffix}_LeadingFinger`, materials.bone,
    new THREE.Vector3(1.06 * side, 1.06, 0.00),
    new THREE.Vector3(1.62 * side, 1.30, -0.01), 0.065, 0.028, 10);

  const fingerTips = [
    [1.46 * side, 0.56, -0.01],
    [1.16 * side, 0.24, -0.015],
    [0.76 * side, -0.10, -0.02],
  ];
  fingerTips.forEach((tip, index) => {
    addSegment(display, `Wing${suffix}_Finger${index + 2}`, materials.bone,
      new THREE.Vector3(1.06 * side, 1.06, 0.00),
      new THREE.Vector3(tip[0], tip[1], tip[2]), 0.05, 0.016, 8);
  });

  // 翼膜：带真实厚度的多边形，后缘做扇形缺口
  const outline = wingOutline(side);
  const shape = new THREE.Shape();
  shape.moveTo(outline[0][0], outline[0][1]);
  for (let index = 1; index < outline.length; index += 1) {
    shape.lineTo(outline[index][0], outline[index][1]);
  }
  shape.closePath();
  const membraneGeometry = new THREE.ExtrudeGeometry(shape, {
    depth: 0.05,
    steps: 1,
    bevelEnabled: false,
    curveSegments: 1,
  });
  membraneGeometry.translate(0, 0, -0.025);
  const membrane = new THREE.Mesh(membraneGeometry, materials.membrane);
  membrane.name = `Wing${suffix}Root_Wing${suffix}Membrane`;
  display.add(membrane);

  // 翼膜上的骨脊，增加可读性
  const ribs = [
    [[0.30, 0.18], [1.42, 0.55]],
    [[0.40, 0.10], [1.16, 0.22]],
    [[0.50, 0.02], [0.78, -0.08]],
  ];
  ribs.forEach((rib, index) => {
    addSegment(display, `Wing${suffix}_Rib${index + 1}`, materials.bone,
      new THREE.Vector3(rib[0][0] * side, rib[0][1], 0.02),
      new THREE.Vector3(rib[1][0] * side, rib[1][1], 0.02), 0.022, 0.008, 6);
  });

  return root;
}

function buildTail(parent, materials) {
  const tailRoot = makeGroup(parent, 'TailRoot', [0, 1.02, -1.06], [-0.18, 0, 0]);
  const definitions = [
    { name: 'Tail01', length: 0.55, r0: 0.30, r1: 0.26, rx: -0.12 },
    { name: 'Tail02', length: 0.52, r0: 0.26, r1: 0.22, rx: -0.06 },
    { name: 'Tail03', length: 0.48, r0: 0.22, r1: 0.19, rx: 0.02 },
    { name: 'Tail04', length: 0.44, r0: 0.19, r1: 0.16, rx: 0.14 },
    { name: 'Tail05', length: 0.38, r0: 0.16, r1: 0.13, rx: 0.26 },
    { name: 'Tail06', length: 0.32, r0: 0.13, r1: 0.10, rx: 0.38 },
    { name: 'Tail07', length: 0.26, r0: 0.10, r1: 0.07, rx: 0.46 },
  ];

  let parentNode = tailRoot;
  let offsetZ = 0;
  definitions.forEach((definition, index) => {
    const pivot = makeGroup(parentNode, definition.name, [0, 0, offsetZ], [definition.rx, 0, 0]);
    addSegment(pivot, `${definition.name}_Shell`, materials.hide,
      new THREE.Vector3(0, 0, 0),
      new THREE.Vector3(0, 0, -definition.length), definition.r0, definition.r1, 14);
    addJoint(pivot, `${definition.name}_Joint`, materials.hide, [0, 0, 0], definition.r0, 14);
    addCone(pivot, `${definition.name}_Spike`, materials.bone,
      new THREE.Vector3(0, definition.r0 * 0.6, -definition.length * 0.35),
      new THREE.Vector3(0, definition.r0 * 0.6 + 0.14, -definition.length * 0.35 - 0.12),
      0.04, 8);
    if (index === definitions.length - 1) {
      buildTailBlade(pivot, materials, definition.length);
    }
    parentNode = pivot;
    offsetZ = -definition.length;
  });

  return tailRoot;
}

function buildTailBlade(parent, materials, lastLength) {
  const bladeRoot = makeGroup(parent, 'TailBlade', [0, 0, -lastLength + 0.02]);
  // 深红内刃
  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.lineTo(0.10, 0.10);
  finShape.lineTo(0.20, 0.42);
  finShape.lineTo(0.06, 0.33);
  finShape.lineTo(-0.02, 0.48);
  finShape.lineTo(-0.10, 0.26);
  finShape.lineTo(-0.16, 0.10);
  finShape.closePath();
  const finGeometry = new THREE.ExtrudeGeometry(finShape, {
    depth: 0.035,
    steps: 1,
    bevelEnabled: false,
  });
  finGeometry.translate(0, 0, -0.0175);
  const fin = new THREE.Mesh(finGeometry, materials.bladeRed);
  fin.name = 'TailBlade_RedFin';
  fin.rotation.y = Math.PI * 0.5;
  bladeRoot.add(fin);

  // 外骨刃
  const bladeSegments = [
    [[0, 0.02, 0.0], [0, 0.44, -0.10], 0.09],
    [[0.02, 0.0, 0.0], [0.28, 0.30, -0.10], 0.055],
    [[-0.02, 0.0, 0.0], [-0.28, 0.30, -0.10], 0.055],
    [[0, -0.02, 0.0], [0.10, -0.22, -0.16], 0.045],
  ];
  bladeSegments.forEach((blade, index) => {
    addCone(bladeRoot, `TailBlade_Spike${index + 1}`, materials.bone,
      new THREE.Vector3(blade[0][0], blade[0][1], blade[0][2]),
      new THREE.Vector3(blade[1][0], blade[1][1], blade[1][2]), blade[2], 10);
  });
  return bladeRoot;
}

function buildLeg(parent, materials, side, front) {
  const suffix = `${front ? 'F' : 'B'}${side > 0 ? 'L' : 'R'}`;
  const hip = front
    ? [0.60 * side, 1.56, 0.62]
    : [0.62 * side, 1.12, -0.66];
  const knee = front
    ? [0.68 * side, 0.92, 0.75]
    : [0.75 * side, 0.58, -0.20];
  const ankle = front
    ? [0.71 * side, 0.32, 0.86]
    : [0.79 * side, 0.24, -0.70];
  const foot = front
    ? [0.72 * side, 0.15, 1.02]
    : [0.81 * side, 0.15, -0.40];

  const root = makeGroup(parent, `Leg${suffix}`, hip);
  addJoint(root, `Leg${suffix}_Hip`, materials.hide, [0, 0, 0], front ? 0.20 : 0.27, 14);
  addSegment(root, `Leg${suffix}_Upper`, materials.hide,
    new THREE.Vector3(0, 0, 0),
    new THREE.Vector3(knee[0] - hip[0], knee[1] - hip[1], knee[2] - hip[2]),
    front ? 0.19 : 0.27, front ? 0.14 : 0.19, 14);
  addJoint(root, `Leg${suffix}_Knee`, materials.hide,
    [knee[0] - hip[0], knee[1] - hip[1], knee[2] - hip[2]], front ? 0.14 : 0.19, 14);
  addSegment(root, `Leg${suffix}_Lower`, materials.hide,
    new THREE.Vector3(knee[0] - hip[0], knee[1] - hip[1], knee[2] - hip[2]),
    new THREE.Vector3(ankle[0] - hip[0], ankle[1] - hip[1], ankle[2] - hip[2]),
    front ? 0.13 : 0.17, front ? 0.10 : 0.115, 12);
  addJoint(root, `Leg${suffix}_Ankle`, materials.hide,
    [ankle[0] - hip[0], ankle[1] - hip[1], ankle[2] - hip[2]], front ? 0.10 : 0.115, 12);
  addEllipsoid(root, `Leg${suffix}_Foot`, materials.hideDark,
    [foot[0] - hip[0], foot[1] - hip[1], foot[2] - hip[2]],
    [0.18, 0.10, front ? 0.28 : 0.30], 18, 12);

  const clawBaseZ = foot[2] + (front ? 0.20 : 0.18);
  const clawSpread = [-0.12, 0, 0.12];
  clawSpread.forEach((spread, index) => {
    const baseX = foot[0] + spread;
    addCone(root, `Leg${suffix}_Claw${index + 1}`, materials.claw,
      new THREE.Vector3(baseX - hip[0], 0.16 - hip[1], clawBaseZ - hip[2]),
      new THREE.Vector3(baseX + spread * 0.35 - hip[0], 0.03 - hip[1], clawBaseZ + 0.24 - hip[2]),
      0.045, 8);
  });
  // 后腿额外脚趾向后的一枚爪
  if (!front) {
    addCone(root, `Leg${suffix}_ClawRear`, materials.claw,
      new THREE.Vector3(foot[0] - hip[0], 0.16 - hip[1], foot[2] - 0.18 - hip[2]),
      new THREE.Vector3(foot[0] - hip[0], 0.05 - hip[1], foot[2] - 0.34 - hip[2]), 0.04, 8);
  }
  return root;
}

function buildSaddle(parent, materials) {
  const saddle = addEllipsoid(parent, 'Saddle', materials.saddleLeather, [0, 1.95, -0.52], [0.40, 0.105, 0.54], 24, 14);
  addEllipsoid(saddle, 'Saddle_Cantle', materials.saddleLeather, [0, 0.05, -0.34], [0.30, 0.10, 0.12], 18, 10);
  addEllipsoid(saddle, 'Saddle_Pommel', materials.saddleLeather, [0, 0.04, 0.36], [0.26, 0.08, 0.10], 18, 10);

  const strapPositions = [0.34, -0.34];
  strapPositions.forEach((x, index) => {
    const strap = addEllipsoid(saddle, `Saddle_Strap${index + 1}`, materials.saddleLeather,
      [x, -0.32, -0.02], [0.055, 0.36, 0.055], 12, 8);
    strap.rotation.z = x > 0 ? -0.28 : 0.28;
    addEllipsoid(saddle, `Saddle_Buckle${index + 1}`, materials.saddleMetal,
      [x * 0.86, -0.58, -0.02], [0.055, 0.045, 0.028], 12, 8);
  });

  const seatAnchor = new THREE.Group();
  seatAnchor.name = 'SeatAnchor';
  seatAnchor.position.set(0, 0.105, 0.04);
  saddle.add(seatAnchor);
  return saddle;
}

module.exports = function previewModule(moduleRoot, runtime) {
  const { helpers, logger } = runtime;
  helpers.clearGroup(moduleRoot);

  const root = new THREE.Group();
  root.name = 'DragonRoot';
  root.userData.assetBrief = ASSET_BRIEF;
  moduleRoot.add(root);

  const visualRoot = makeGroup(root, 'VisualRoot');
  const materials = makeMaterials();

  // 躯干：多个椭圆体互相重叠，形成连续体量
  addEllipsoid(visualRoot, 'Torso_HipsMass', materials.hide, [0, 1.10, -0.82], [0.64, 0.54, 0.62], 26, 18);
  addEllipsoid(visualRoot, 'Torso_Belly', materials.hide, [0, 1.26, -0.12], [0.62, 0.64, 0.92], 28, 18);
  addEllipsoid(visualRoot, 'Torso_Chest', materials.hide, [0, 1.46, 0.58], [0.68, 0.58, 0.64], 28, 18);
  addEllipsoid(visualRoot, 'Torso_Shoulders', materials.hide, [0, 1.58, 0.44], [0.82, 0.44, 0.52], 24, 16);
  addEllipsoid(visualRoot, 'Torso_NeckBase', materials.hide, [0, 1.74, 0.84], [0.38, 0.36, 0.40], 20, 14);
  addEllipsoid(visualRoot, 'Torso_TailRoot', materials.hide, [0, 1.02, -1.05], [0.39, 0.38, 0.42], 20, 14);

  buildBellyPlates(visualRoot, materials);
  buildDorsalSpikes(visualRoot, materials);
  buildNeck(visualRoot, materials);
  buildWing(visualRoot, materials, 1);
  buildWing(visualRoot, materials, -1);
  buildTail(visualRoot, materials);
  buildLeg(visualRoot, materials, 1, true);
  buildLeg(visualRoot, materials, -1, true);
  buildLeg(visualRoot, materials, 1, false);
  buildLeg(visualRoot, materials, -1, false);
  buildSaddle(visualRoot, materials);

  // 肩部与翼根之间的过渡体量，避免翅膀像插在空气里
  addEllipsoid(visualRoot, 'WingLeftRoot_ShoulderMass', materials.hide, [0.52, 1.92, 0.30], [0.20, 0.22, 0.24], 16, 12);
  addEllipsoid(visualRoot, 'WingRightRoot_ShoulderMass', materials.hide, [-0.52, 1.92, 0.30], [0.20, 0.22, 0.24], 16, 12);

  // 腹部与颈部下方更亮的甲片过渡，呼应参考图的分节纹理
  addEllipsoid(visualRoot, 'NeckUnderPlate1', materials.bellyPlate, [0, 1.92, 0.96], [0.22, 0.10, 0.16], 16, 10);
  addEllipsoid(visualRoot, 'NeckUnderPlate2', materials.bellyPlate, [0, 2.10, 1.08], [0.19, 0.09, 0.14], 16, 10);
  addEllipsoid(visualRoot, 'NeckUnderPlate3', materials.bellyPlate, [0, 2.28, 1.20], [0.16, 0.08, 0.12], 16, 10);

  root.traverse((object) => {
    if (!object.isMesh) return;
    object.castShadow = true;
    object.receiveShadow = true;
  });

  logger.info('Black dragon mount built');
};

